"""Writes report.md from results.json and parameters.json (called by build_bench.py)."""
import json
import math
from pathlib import Path


def n(x, nd=1):
    return f"{x:,.{nd}f}" if isinstance(x, (int, float)) else str(x)


def write(r, here):
    here = Path(here)
    P = json.load(open(here / "parameters.json", encoding="utf-8"))
    W = P["world_figures"]
    m, d, sl, fr, c = r["mass"], r["dims"], r["slats"], r["frame"], r["casting"]
    pk, pa, t = r["packaging"], r["parcels"], r["transport"]
    f = P["frame"]
    g = 9.81
    cast_bench = 2 * (m["frame_bare"] + m["frame_draft"])
    melt_loss = c["poured"] * P["casting"]["melt_loss_pct"] / 100
    fettle = 2 * P["casting"]["fettling_loss_kg_per_frame"]
    fix_steel = P["bolts"]["count"] * (m["bolt"] + m["washer"] + m["nut"])
    net_liquid = cast_bench + melt_loss + fettle
    blank_l = 1830 * 101 * 44 / 1e6
    blank_kg = blank_l * P["materials"]["wood_density"] / 1000
    rough_bench = 5 * blank_kg
    roundwood_m3 = 5 * blank_l / 1000 * 1.8
    ur = sl["cases"]["UR-SF-0450 (450 kg over the seat)"]
    urw = sl["cases"]["UR-SF-0450, E from the Wood Handbook (oak, +10 % shear)"]
    enc = sl["cases"]["EN 581-2 contract, 2000 N on the centre seat"]
    ene = sl["cases"]["EN 581-2 contract, 2000 N on an end seat"]
    enb = sl["cases"]["EN 581-2 back 560 N, all on the upper back slat, centre seat"]
    svc = sl["cases"]["Three adults of 80 kg, one per seat (service)"]
    fcases = fr["cases"]
    co, ci = pk["carton_outer"], pk["carton_inner"]
    bu = pk["bundle"]
    fb = pk["frame_bbox"]
    wall = r["frame_mass_by_wall"]
    zinc_pc = m["zinc_typ"] + m["powder"]
    arm_extra = (f["x_centre"] - f["armrest"]["flange_width"] / 2) * f["t_flange"] * 547 * P["materials"]["steel_density"] / 1e9
    N_ITEMS = 17
    world_net_check = 2 * W["frame_mass"] + 5 * W["slat_mass"] + W["bolt_set_mass"]
    D20_bar = W["frame_section_mm"][0] * W["frame_section_mm"][1] * W["frame_member_length_m"] * 1000 / 1e6
    seat_bar_W = W["frame_section_mm"][0] * W["frame_section_mm"][1] ** 2 / 6

    L = []
    A = L.append
    A("# Serra 180 park bench: parametric model, drawings and check of the world's figures")
    A("")
    A(f"*Valdara Industries, Ferrano (Urvania), item VI-B180, datasheet VI-DS-B180. Model of 2026-11-17 for open point O149 "
      f"(feeds O25 and C69). Generated by `build_bench.py` from `parameters.json`; every number below is computed, none is typed in.*")
    A("")
    A("## 1. Summary")
    A("")
    A(f"- **What was made:** a parametric solid model of the bench (two identical cast-steel side frames, five hardwood slats, 20 M8 carriage bolts), "
      f"STEP files of the assembly and each part, GLB files for the web, eight dimensioned SVG drawings (drawing numbers VI-DWG-B180-001 to 008), "
      f"five PNG renders, the mould with gating and risers, the parcels and the pallet, and this report with all figures in `results.json`.")
    A(f"- **The bench as designed:** {n(d['length'], 0)} mm over the slats, **{n(d['over_armrests'], 0)} mm over the armrests**, {n(d['depth'], 0)} mm deep, "
      f"{n(d['height'], 0)} mm high; seat {n(d['seat_front'], 0)} mm (440 to 460 on levelling nuts); 3 seat slats and 2 back slats; seat tilt "
      f"{P['ergonomics']['seat_tilt_deg']}°, seat to back {P['ergonomics']['seat_back_angle_deg']}°; armrests 200 mm above the seat.")
    A(f"- **Key figures against the world:** side frame **{n(m['frame_bare'], 1)} kg cast, {n(m['frame'], 1)} kg galvanised and coated** (world 10.0 + 0.2); "
      f"bench **net {n(m['net'], 1)} kg** (world 43.5), **gross {n(pa['gross'], 1)} kg** in three parcels of {n(pa['carton1'], 1)}, {n(pa['carton2'], 1)} and "
      f"{n(pa['bundle'], 1)} kg (world 10.2 / 11.2 / 23.0 = 44.4); frame carton {n(co[0], 0)} x {n(co[1], 0)} x {n(co[2], 0)} mm (world 820 x 620 x 80); "
      f"pallet of four {n(t['pallet_dims'][0], 0)} x {n(t['pallet_dims'][1], 0)} x {n(t['pallet_dims'][2], 0)} mm, {n(t['pallet_goods_kg'], 0)} kg of goods, "
      f"{n(t['pallet_gross_kg'], 0)} kg gross (world 1850 x 650 x 750, 178 / 200 kg); metal poured **{n(c['poured'], 1)} kg per bench at "
      f"{n(100 * c['yield_'], 0)} % yield** (world 34 kg at 60 %); steel in the product {n(m['steel_in_product'], 1)} kg (world about 21).")
    A(f"- **Strength:** the frame is lightly stressed (at most {n(max(v['sigma_max'] for v in fcases.values()), 0)} MPa against "
      f"Rp0.2 = 240 MPa); its walls are set by castability, not by the load. The slats are the critical part: {n(ur['sigma'], 1)} MPa and "
      f"{n(ur['w_span'], 0)} mm deflection under the 450 kg test (Eurocode 5 utilisation {n(ur['util_d'], 2)}).")
    A(f"- **Inconsistencies:** {N_ITEMS} are listed in section 6; the largest are the length over the armrests, the frame mass, the zero-mass cartons, "
      "the carton and pallet widths, the metal poured, and ash and beech as outdoor slat woods.")
    A("")
    A("## 2. Files")
    A("")
    A("| Path | Content |")
    A("|---|---|")
    A("| `parameters.json` | the single source of truth (dimensions, materials, loads, packaging, the world's figures for comparison) |")
    A("| `build_bench.py`, `report.py`, `render.js` | generator (geometry, analysis, STEP/GLB/SVG), this report, the renders; see `README.md` |")
    A("| `results.json` | every derived figure |")
    A("| `step/VI-B180_assembly.step` | the bench; parts `VI-C180_side_frame.step`, `VI-B180-03_slat.step`, `VI-B180-04_fixing_M8.step`; also `VI-C180_mould_cluster.step` (one mould: two castings, risers, gating) and `VI-B180_pallet.step` |")
    A("| `glb/` | `serra180_GRY.glb`, `serra180_GRN.glb`, `serra180_parcels.glb`, `serra180_pallet.glb` (metres, Y up) |")
    A("| `drawings/` | 001 general arrangement, 002 side frame with sections, 003 slat, 004 exploded assembly, 005 bill of materials, 006 parcels, 007 pallet and loading, 008 casting method |")
    A("| `renders/` | three-quarter view in Ferro grey and Moss green, frame and slat detail, the three parcels, the pallet of four |")
    A("")
    A("Colours in the renders are approximations: Ferro grey as RAL 7011 (sRGB about #555D61) and Moss green as RAL 6005 (about #114232). "
      "RAL publishes no official sRGB values.")
    A("")
    A("## 3. The design and the reasons for it")
    A("")
    A("### 3.1 Ergonomics and overall form")
    A("")
    A(f"- **Seat height {n(d['seat_front'], 0)} mm** at the front edge (fixed by the owner), with the frames standing {P['overall']['levelling_gap_nominal']} mm above "
      f"the plinth on the levelling nuts of the ground anchors; 0 to 20 mm of gap gives the 440 to 460 mm range, and the gap is grouted after levelling. "
      f"UK guidance (Inclusive Mobility, 2021, p. 102) asks for 470 to 480 mm for most seats; the US 2010 ADA Standards (903.5) allow 430 to 485 mm for benches. "
      f"450 is below the UK range (inconsistency 13).")
    A(f"- **Armrests 200 mm above the seat** ({n(d['seat_front'] + P['ergonomics']['armrest_above_seat'], 0)} mm above the ground), as Inclusive Mobility recommends; "
      f"seat width between the armrests {n(d['between_armrests'], 0)} mm = 3 x {n(d['seat_width_per_person'], 0)} mm, above its 500 mm per person.")
    A(f"- **Seat tilt {P['ergonomics']['seat_tilt_deg']}° and seat-to-back angle {P['ergonomics']['seat_back_angle_deg']}°** (back {n(d['beta'], 0)}° from vertical): "
      f"within the usual 0–5° seat tilt and 100–110° seat-to-back angle of seating handbooks (Pheasant and Haslegrave, *Bodyspace*, quoted from "
      f"general knowledge, not checked here). Water runs off the tilted seat and through the gaps, as Inclusive Mobility asks for outdoor seats.")
    A(f"- **Seat depth {P['ergonomics']['seat_depth']} mm** from the front edge to the line of the back. Three slats and two gaps of {P['slats']['seat_gap']} mm give "
      f"{n(d['seat_surface_depth'], 0)} mm of slat surface; the remaining {n(d['throat'], 0)} mm is an open throat between seat and back (room for the buttocks, "
      f"debris falls through). ADA 903.3 asks 510–610 mm for benches used for transfer; that is a building-code rule for benches in rooms and is not applied here.")
    A(f"- **Back:** two slats, at {n(d['back_rel_P'][0], 0)}–{n(d['back_rel_P'][1], 0)} mm (lumbar) and {n(d['back_rel_P'][2], 0)}–{n(d['back_rel_P'][3], 0)} mm "
      f"above the seat-back junction; top of the back {n(d['back_height_above_seat'], 0)} mm above the seat front, at the {n(d['height'], 0)} mm "
      f"of the brief. UK design guides ask at least 300 mm of back above the seat; ADA 903.4 would ask 455 mm (not applied).")
    A(f"- **Depth {n(d['depth'], 0)} mm**: the rear feet end at 620 mm and the top of the back rail at about {n(d['back_rail_top_y'], 0)} mm; the brief's depth is only just enough for "
      f"the back angle chosen.")
    A(f"- **Gaps around the armrest**: the armrest passes between the two back slats to the back rail, {n(d['arm_clear_lower'], 0)} mm above the lower slat and "
      f"{n(d['arm_clear_upper'], 0)} mm below the upper one, both above 25 mm so that no gap is in the 8–25 mm range that traps fingers (the playground rule "
      f"EN 1176-1, used as a conservative reference because children use park benches; quoted from general knowledge). The post stands {P['slats']['post_to_slat_gap']} mm "
      f"in front of the front seat slat, below the 8 mm limit.")
    A("")
    A("### 3.2 Side frame")
    A("")
    A(f"- **One casting for both sides.** The spare part VI-C180 is one frame, so the frame is symmetric about its own mid-plane: all members are T-sections "
      f"with the web in the frame plane and the flange centred on it. Left and right frames are the same casting. The parting line is the web mid-plane, "
      f"so the pattern splits in two halves and needs no cores.")
    A(f"- **Members:** front post ({f['front_post']['depth']} mm deep, flange {f['front_post']['flange_width']}), armrest ({f['armrest']['depth']}, pad {f['armrest']['flange_width']}), "
      f"seat rail ({f['seat_rail']['depth']}, flange {f['seat_rail']['flange_width']}), back rail ({f['back_rail']['depth']}, flange {f['back_rail']['flange_width']}), "
      f"rear leg ({f['rear_leg']['depth']}, flange {f['rear_leg']['flange_width']}), "
      f"two feet {f['feet']['width']} x 120 x {f['feet']['thickness']} mm with one Ø{f['feet']['hole_diameter']} anchor hole each (four M12 ground anchors in all, the separate item). "
      f"Walls **{f['t_web']} mm** throughout; concave radii R{f['fillet_concave']}, edges R{f['round_convex']}; draft {f['draft_deg']}° (allowed for as "
      f"{f['draft_mass_allowance_pct']} % of the mass, not modelled).")
    A(f"- **Why 8 mm:** the Steel Founders' Society of America (SFSA) gives 6 mm as the minimum section for conventional sand-cast steel, and states that thin sections "
      f"must also be limited in length so that the metal fills the mould. The members here are 240 to 550 mm long and fed from one end; 8 mm is chosen as 6 mm plus a "
      f"margin for flow length (SFSA's thickness-versus-length chart could not be opened from here, so the margin is a judgement). At 6 mm the frame would weigh "
      f"{n(wall['6'], 1)} kg, at 7 mm {n(wall['7'], 1)} kg, at 8 mm {n(wall['8'], 1)} kg, at 10 mm {n(wall['10'], 1)} kg (bare casting).")
    A(f"- **Material:** GE240+N to EN 10293 (Rp0.2 ≥ 240 MPa, Rm 450–600 MPa), a plain carbon cast steel that suits an integrated works melting its own steel "
      f"from Serravona ore. G20Mn5+N (Rp0.2 ≥ 300 MPa, impact-tested at −30 °C) would be the choice if the frames needed toughness in frost; not needed here.")
    A(f"- **Galvanising (EN ISO 1461, design to ISO 14713-2):** open T-sections only, no closed cavities, no overlapping surfaces; the frame is hung from the two anchor holes with "
      f"the armrest down, so zinc drains to the armrest end. Castings of 6 mm and more get at least 80 µm (575 g/m²) mean; on the modelled surface of "
      f"{n(m['frame_area_m2'], 3)} m² that is {n(m['zinc_min'], 2)} kg, taken as {n(m['zinc_typ'], 2)} kg typical. Castings are shot-blasted before galvanising "
      f"(sand inclusions). Then a duplex polyester powder coat of {P['materials']['powder_coat']['thickness_um']} µm ({n(m['powder'], 2)} kg) in the frame colour.")
    A(f"- **Bolting:** each slat is held at each frame by two M8 cup-square-neck (carriage) bolts on the slat's centre line, one each side of the web "
      f"(x = web ± 20 mm), through Ø10 holes in the flange; washer and nut under the flange. The two bolts lie along the grain, so they do not restrain the "
      f"slat's swelling across its width (about 2–3 mm between 12 % and 20 % moisture), which two bolts across the width would, splitting the slat. "
      f"End distance 80 mm from the slat end = max(7d; 80 mm) of EN 1995-1-1 Table 8.4 for a loaded end (racking pushes the bolts towards the ends); spacing 40 mm = 5d "
      f"along the grain. This fixes the frames at {f['x_centre']} mm from the slat ends, which is why the armrests cannot reach the slat ends (inconsistency 1).")
    A(f"- **Melt and serial numbers:** the melt number is cast in with loose letters for each casting day; a serial number per frame cannot sensibly be cast in "
      f"(each mould would need its own number inserts), so it is hard-stamped after fettling. The world's 'serial number per frame' holds.")
    A("")
    A("### 3.3 Slats")
    A("")
    A(f"- 1,800 x 95 x 38 mm as delivered (fixed); edges chamfered 3 mm; four Ø9 holes on the centre line at 80 and 120 mm from each end. Same slat for seat and back. "
      f"Modelled volume {n(m['slat_volume_l'], 3)} l (the full box is {n(m['slat_box_volume_l'], 3)} l), mass at 690 kg/m³ **{n(m['slat'], 2)} kg** (world 4.5).")
    A(f"- Strength class EN 338 D30, the class visually graded European oak reaches (f_m,k = 30 MPa, E0,mean taken as 11,000 MPa; a study of Central European hardwoods "
      f"gives oak LS10 E = 11,500 MPa). The Wood Handbook (FPL-GTR-282, Table 5-3a) gives clear white oak at 12 %: MOR 105 MPa, MOE 12,300 MPa, specific gravity 0.68.")
    A("")
    A("### 3.4 Casting method (drawing 008)")
    A("")
    A(f"- One mould per bench: the two frames lie flat, mirrored, with their main junctions J facing each other across a {n(c['runner_len'], 0)} mm runner; "
      f"sprue between them; one ingate into each J (gating into the heaviest node). Pour {n(c['W_guess'], 0)} kg in about {n(c['t_pour'], 0)} s "
      f"(t = 1.4√W, a rule of thumb); 250 mm head, discharge coefficient 0.8: choke {n(c['A_choke'], 0)} mm² (sprue Ø{n(c['d_sprue'], 0)}), gating ratio 1 : 2 : 2, "
      f"runner {n(c['run_w'], 0)} x {n(c['run_h'], 0)} mm, ingates {n(c['gate_w'], 0)} x {n(c['gate_t'], 0)} mm.")
    A(f"- Risers by the modulus method: modulus of the wall section {n(c['M_wall'], 1)} mm (area / cooling perimeter), {n(c['M_j'], 1)} mm at junctions (x 1.5, the "
      f"inscribed-circle effect), riser modulus x 1.2 = {n(c['M_r'], 1)} mm; a top riser with H = 1.5 D has M = D·H/(4H + D) = 0.214 D, so D = {n(c['D_calc'], 1)} mm, "
      f"used as Ø{n(c['D'], 0)} x {n(c['H'], 0)} mm.")
    A(f"- Feeding distance by the SFSA bar rule FD = 6√T (inches) = {n(c['FD'], 0)} mm each side of a riser for T = 8 mm. That needs, besides the six junction risers, "
      f"intermediate risers along the members: " + ", ".join(f"{x['run']} {x['length']} mm: {x['intermediate_risers']}" for x in c["runs"]) +
      f" — **{c['n_risers']} risers per frame**.")
    A(f"- Result: castings {n(2 * c['casting_kg'], 1)} kg per mould, risers {n(2 * c['riser_kg'], 1)} kg, gating and basin {n(c['gating_kg'], 1)} kg: "
      f"**poured {n(c['poured'], 1)} kg, yield {n(100 * c['yield_'], 0)} %.** With junction risers only (accepting centre-line shrinkage in the bars, "
      f"which a lightly loaded part can tolerate but which can bleed through the zinc): {n(c['poured_j'], 1)} kg, {n(100 * c['yield_j'], 0)} %.")
    A("")
    A("### 3.5 Packaging (drawings 006 and 007)")
    A("")
    A(f"- **Frame carton:** the frame is {n(fb[2], 0)} x {n(fb[1], 0)} x {n(fb[0], 0)} mm (height x depth x thickness). Lying flat with 20 / 20 / 10 mm of clearance "
      f"for corner pads, the inside is {n(ci[0], 0)} x {n(ci[1], 0)} x {n(ci[2], 0)} mm; a FEFCO 0320 tray and lid in single-wall C flute (560 g/m²) gives "
      f"**{n(co[0], 0)} x {n(co[1], 0)} x {n(co[2], 0)} mm** outside and weighs {n(pk['carton_kg'], 2)} kg with pads.")
    A(f"- **Slat bundle:** five slats in a 3 + 2 pattern (broad faces down, top row centred), corrugated edge protectors, end caps, four PET straps and film: "
      f"**{n(bu[0], 0)} x {n(bu[1], 0)} x {n(bu[2], 0)} mm**, packing {n(pk['bundle_pack_kg'], 2)} kg. Two bundles side by side make a 590 mm wide, flat bed for the cartons.")
    A(f"- **Pallet of four benches:** a four-way block pallet {P['packaging']['pallet']['length']} x {P['packaging']['pallet']['width']} x {n(pk['pallet_h'], 0)} mm "
      f"of heat-treated softwood (ISPM 15), {n(pk['pallet_kg'], 1)} kg; four bundles (2 x 2) at the bottom, a slip sheet, eight cartons in two columns of four, a top cap, "
      f"corner boards and film: **{n(t['pallet_dims'][0], 0)} x {n(t['pallet_dims'][1], 0)} x {n(t['pallet_dims'][2], 0)} mm**, goods {n(t['pallet_goods_kg'], 1)} kg, "
      f"**gross {n(t['pallet_gross_kg'], 1)} kg**. Fork-lift; stacks up to {t['stack_max']} high by height in all three vehicles.")
    A(f"- **Vehicles:** with the pallet 1,850 long and 700 wide, three fit across and seven (trailer, 45-foot) or six (40-foot) along: {t['trailer']['floor']}, "
      f"{t['container_40']['floor']} and {t['container_45']['floor']} floor positions, as the world says. 24 bench pallets and the castings pallet "
      f"({n(t['castings_pallet_kg'], 0)} kg, 12 cartons) need {t['floor_needed']} positions in two layers; load {n(t['load_kg'] / 1000, 2)} t, well within every payload.")
    A("")
    A("## 4. Derived figures")
    A("")
    A("### 4.1 Masses")
    A("")
    A("| Part | Volume | Mass |")
    A("|---|---|---|")
    A(f"| Side frame, cast (modelled) | {n(m['frame_volume_l'], 3)} l | {n(m['frame_bare'], 2)} kg |")
    for k, v in m["breakdown_kg"].items():
        A(f"| — of which {k} (approx., overlaps counted twice) | {n(m['breakdown_l'][k], 3)} l | {n(v, 2)} kg |")
    A(f"| Draft allowance {f['draft_mass_allowance_pct']} % | | {n(m['frame_draft'], 2)} kg |")
    A(f"| Zinc, EN ISO 1461 minimum / typical (surface {n(m['frame_area_m2'], 3)} m²) | | {n(m['zinc_min'], 2)} / {n(m['zinc_typ'], 2)} kg |")
    A(f"| Powder coat {P['materials']['powder_coat']['thickness_um']} µm | | {n(m['powder'], 2)} kg |")
    A(f"| **Side frame, finished (each)** | | **{n(m['frame'], 2)} kg** |")
    A(f"| Slat (each) | {n(m['slat_volume_l'], 3)} l | {n(m['slat'], 2)} kg |")
    A(f"| Carriage bolt M8 x 60 / washer / nut (steel; bolt x {P['bolts']['thread_mass_factor']} for the thread) | | {n(1000 * m['bolt'], 1)} / {n(1000 * m['washer'], 1)} / {n(1000 * m['nut'], 1)} g |")
    A(f"| Bolt set: 20 fixings, galvanised, in a bag | | {n(m['boltset'], 2)} kg |")
    A(f"| **Bench, net** | | **{n(m['net'], 2)} kg** |")
    A(f"| Steel in the product (castings with draft, fasteners; no zinc) | | {n(m['steel_in_product'], 1)} kg |")
    A("")
    A(f"Centre of gravity of the bench (frames and slats): x = {n(m['bench_cg'][0], 0)}, y = {n(m['bench_cg'][1], 0)} mm behind the front, "
      f"z = {n(m['bench_cg'][2], 0)} mm above the ground. Centre of gravity of a frame: y = {n(m['frame_cg'][1], 0)}, z = {n(m['frame_cg'][2], 0)} mm.")
    A("")
    A("### 4.2 Metal, steel and wood per bench")
    A("")
    A("| Figure | Value |")
    A("|---|---|")
    A(f"| Castings (2 frames, with draft) | {n(cast_bench, 1)} kg |")
    A(f"| Metal poured, risers by the SFSA rule ({c['n_risers']} per frame) | {n(c['poured'], 1)} kg, yield {n(100 * c['yield_'], 0)} % |")
    A(f"| Metal poured, junction risers only | {n(c['poured_j'], 1)} kg, yield {n(100 * c['yield_j'], 0)} % |")
    A(f"| Returns remelted (risers, gating) | {n(c['poured'] - 2 * c['casting_kg'], 1)} kg |")
    A(f"| Liquid steel consumed net: castings + melt loss {P['casting']['melt_loss_pct']} % of poured + fettling (assumed rates) | {n(net_liquid, 1)} kg |")
    A(f"| Fasteners (bought-in or own) | {n(fix_steel, 2)} kg |")
    A(f"| Hardwood in the product (5 slats) | {n(5 * m['slat'], 1)} kg |")
    A(f"| Kiln-dried rough-sawn hardwood, 5 blanks of 1,830 x 101 x 44 mm before planing (assumed allowances) | {n(rough_bench, 1)} kg |")
    A(f"| Roundwood, at about 1.8 m³ of logs per m³ of hardwood sawnwood (assumed) | {n(roundwood_m3, 3)} m³ |")
    A("")
    A("### 4.3 Parcels and pallet")
    A("")
    A("| Unit | Size (mm) | Gross mass | Handling |")
    A("|---|---|---|---|")
    A(f"| Parcel 1: frame carton | {n(co[0], 0)} x {n(co[1], 0)} x {n(co[2], 0)} | {n(pa['carton1'], 1)} kg | one person (≤ 25 kg) |")
    A(f"| Parcel 2: frame carton with bolt set | {n(co[0], 0)} x {n(co[1], 0)} x {n(co[2], 0)} | {n(pa['carton2'], 1)} kg | one person |")
    A(f"| Parcel 3: slat bundle | {n(bu[0], 0)} x {n(bu[1], 0)} x {n(bu[2], 0)} | {n(pa['bundle'], 1)} kg | two people (length) |")
    A(f"| Bench, three parcels | | **{n(pa['gross'], 1)} kg** (packaging {n(pa['packaging'], 2)} kg) | |")
    A(f"| Spare frame VI-C180 in its carton | {n(co[0], 0)} x {n(co[1], 0)} x {n(co[2], 0)} | {n(pa['carton1'], 1)} kg | one person |")
